INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ersetzt CIDR die traditionellen IPv4-Klassen (A, B, C)?', 2, '[{"text": "Ja", "correct": true, "because": "CIDR ermöglicht flexiblere Subnetze ohne feste Klassen"}, {"text": "Nein", "correct": false, "because": "CIDR hat Klassen weitgehend abgelöst"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird bei CIDR die Subnetzmaske in Bits angegeben?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. /24 bedeutet 24 Bits für das Netzwerk"}, {"text": "Nein", "correct": false, "because": "Die Bit-Angabe ist zentral für CIDR"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine CIDR-Notation wie 192.168.1.0/24 mehr als 256 Adressen umfassen?', 2, '[{"text": "Nein", "correct": true, "because": "/24 entspricht 256 Adressen (inkl. Netzwerk und Broadcast)"}, {"text": "Ja", "correct": false, "because": "Die Größe ist durch /24 begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist CIDR auch für IPv6 relevant?', 2, '[{"text": "Ja", "correct": true, "because": "CIDR wird auch bei IPv6 für Subnetzmasken genutzt"}, {"text": "Nein", "correct": false, "because": "CIDR ist universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Verringert CIDR die Anzahl der verschwendeten IP-Adressen im Vergleich zu Klassensystemen?', 2, '[{"text": "Ja", "correct": true, "because": "CIDR ermöglicht genauere Subnetzgrößen"}, {"text": "Nein", "correct": false, "because": "Effizienz ist ein Hauptvorteil von CIDR"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet die CIDR-Notation /24 bei einer IPv4-Adresse?', 2, '[{"text": "24 Bits für das Netzwerk", "correct": true, "because": "/24 entspricht 255.255.255.0"}, {"text": "24 Bits für die Hosts", "correct": false, "because": "8 Bits bleiben für Hosts"}, {"text": "24 Adressen insgesamt", "correct": false, "because": "Es sind 256 Adressen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele nutzbare Host-Adressen bietet das Netzwerk 10.0.0.0/30?', 3, '[{"text": "2", "correct": true, "because": "/30 hat 4 Adressen, 2 für Netzwerk und Broadcast"}, {"text": "4", "correct": false, "because": "2 sind reserviert"}, {"text": "6", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske entspricht der CIDR-Notation /27?', 2, '[{"text": "255.255.255.224", "correct": true, "because": "/27 bedeutet 27 Netzwerkbits"}, {"text": "255.255.255.240", "correct": false, "because": "Das ist /28"}, {"text": "255.255.255.192", "correct": false, "because": "Das ist /26"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist die Netzwerkadresse für 192.168.1.32/27?', 2, '[{"text": "192.168.1.32", "correct": true, "because": "/27 hat 32 Adressen, 192.168.1.32 ist der Start"}, {"text": "192.168.1.0", "correct": false, "because": "Zu breit für /27"}, {"text": "192.168.1.64", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Hauptvorteil von CIDR gegenüber dem Klassensystem?', 2, '[{"text": "Flexiblere Subnetzgrößen", "correct": true, "because": "CIDR passt Netzwerke an Bedarf an"}, {"text": "Einfachere Konfiguration", "correct": false, "because": "Nicht der Hauptvorteil"}, {"text": "Schnellere Routing-Tabellen", "correct": false, "because": "Indirekter Effekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen beschreiben CIDR korrekt?', 4, '[{"text": "Ersetzt feste Klassen durch variable Subnetzmasken", "correct": true, "because": "CIDR ist classless"}, {"text": "Nutzt Schrägstrich-Notation (z. B. /24)", "correct": true, "because": "Standard bei CIDR"}, {"text": "Beschränkt auf IPv4", "correct": false, "because": "Auch für IPv6"}, {"text": "Reduziert IP-Adressverschwendung", "correct": true, "because": "Effizientere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adressen gehören zum Netzwerk 172.16.0.0/22?', 3, '[{"text": "172.16.0.1", "correct": true, "because": "Liegt im Bereich 172.16.0.0 - 172.16.3.255"}, {"text": "172.16.4.1", "correct": false, "because": "Außerhalb von /22"}, {"text": "172.16.3.254", "correct": true, "because": "Innerhalb des Bereichs"}, {"text": "172.16.2.10", "correct": true, "because": "Innerhalb des Bereichs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert bei einer CIDR-Notation von /29?', 4, '[{"text": "8 Adressen insgesamt", "correct": true, "because": "2^(32-29) = 8"}, {"text": "6 nutzbare Hosts", "correct": true, "because": "2 reserviert für Netzwerk und Broadcast"}, {"text": "Subnetzmaske 255.255.255.248", "correct": true, "because": "29 Bits = 255.255.255.248"}, {"text": "256 Adressen", "correct": false, "because": "Das wäre /24"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet CIDR?', 3, '[{"text": "Effizientere Adressnutzung", "correct": true, "because": "Kleinere Subnetze möglich"}, {"text": "Vereinfachtes Routing", "correct": true, "because": "Kleinere Routing-Tabellen"}, {"text": "Feste Klassenstruktur", "correct": false, "because": "CIDR ist classless"}, {"text": "Bessere Skalierbarkeit", "correct": true, "because": "Flexiblere Netzwerkgrößen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmasken gehören zu CIDR-Notationen?', 3, '[{"text": "255.255.255.192 (/26)", "correct": true, "because": "26 Bits"}, {"text": "255.255.255.0 (/24)", "correct": true, "because": "24 Bits"}, {"text": "255.255.0.0 (/16)", "correct": true, "because": "16 Bits"}, {"text": "255.0.255.0", "correct": false, "because": "Ungültige Maske"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) CIDR verwendet variable Subnetzmasken. b) CIDR ist auf IPv4-Klassen beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CIDR ist classless, nicht klassenbasiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0/25 hat 128 Adressen. b) /25 entspricht 255.255.255.128.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "2^(32-25) = 128, und /25 ist 255.255.255.128"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CIDR reduziert Adressverschwendung. b) /31 ist für Host-Adressen nutzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/31 hat nur 2 Adressen, keine nutzbaren Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) 10.0.0.0/16 hat 65.536 Adressen. b) CIDR ist nur für große Netzwerke geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(32-16) = 65.536, CIDR ist flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CIDR erlaubt Subnetze mit 2 Adressen (/30). b) CIDR wird nicht für Routing verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/30 ist möglich, CIDR optimiert Routing"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

